from solution import Entry, Report, solve

assert solve([], 0) == Report(0, 0, 0), 'fixture 0'
assert solve([], 5) == Report(1, 5, 0), 'fixture 1'
assert solve([], 1) == Report(1, 1, 0), 'fixture 2'
assert solve([Entry(0, 1)], 2) == Report(2, 1, 1), 'fixture 3'
assert solve([Entry(1, 2), Entry(1, 2)], 3) == Report(2, 1, 1), 'fixture 4'
assert solve([Entry(0, 3), Entry(0, 3), Entry(0, 2)], 4) == Report(2, 2, 2), 'fixture 5'
assert solve([Entry(2, 3), Entry(0, 2), Entry(2, 3), Entry(2, 3)], 5) == Report(3, 1, 3), 'fixture 6'
assert solve([Entry(0, 2), Entry(0, 4), Entry(1, 2), Entry(4, 5), Entry(4, 5)], 6) == Report(3, 1, 4), 'fixture 7'
assert solve([Entry(0, 6), Entry(4, 5), Entry(0, 2), Entry(0, 4), Entry(0, 1), Entry(3, 5)], 7) == Report(3, 1, 6), 'fixture 8'
assert solve([Entry(3, 4), Entry(3, 5), Entry(6, 7), Entry(2, 4), Entry(3, 5), Entry(6, 7), Entry(3, 4)], 8) == Report(2, 3, 3), 'fixture 9'
assert solve([Entry(0, 1), Entry(0, 1), Entry(0, 1), Entry(0, 1), Entry(0, 1), Entry(0, 1), Entry(0, 1), Entry(0, 1), Entry(0, 1)], 2) == Report(2, 1, 1), 'fixture 10'
assert solve([Entry(0, 1), Entry(0, 2), Entry(1, 2), Entry(0, 1), Entry(0, 1), Entry(0, 1), Entry(0, 2), Entry(1, 2), Entry(1, 2), Entry(0, 1)], 3) == Report(3, 1, 3), 'fixture 11'
assert solve([Entry(1, 2), Entry(2, 3), Entry(1, 3), Entry(0, 3), Entry(1, 3), Entry(2, 3), Entry(0, 3), Entry(0, 1), Entry(2, 3), Entry(2, 3), Entry(1, 2)], 4) == Report(4, 1, 6), 'fixture 12'
assert solve([Entry(1, 4), Entry(3, 4), Entry(2, 4), Entry(2, 3), Entry(0, 3), Entry(1, 3), Entry(1, 4), Entry(1, 2), Entry(3, 4), Entry(3, 4), Entry(0, 4), Entry(3, 4)], 5) == Report(4, 1, 6), 'fixture 13'
assert solve([], 6) == Report(1, 6, 0), 'fixture 14'
assert solve([Entry(2, 3)], 7) == Report(2, 1, 1), 'fixture 15'
assert solve([Entry(3, 4), Entry(3, 5)], 8) == Report(2, 2, 2), 'fixture 16'
assert solve([Entry(0, 1), Entry(0, 1), Entry(0, 1), Entry(0, 1)], 2) == Report(2, 1, 1), 'fixture 17'
assert solve([Entry(1, 2), Entry(1, 2), Entry(0, 2), Entry(1, 2), Entry(1, 2)], 3) == Report(2, 1, 1), 'fixture 18'
assert solve([Entry(0, 1), Entry(1, 2), Entry(1, 3), Entry(2, 3), Entry(2, 3), Entry(2, 3)], 4) == Report(4, 1, 6), 'fixture 19'
assert solve([Entry(1, 2), Entry(2, 3), Entry(1, 3), Entry(0, 2), Entry(0, 1), Entry(2, 3), Entry(1, 4)], 5) == Report(4, 1, 8), 'fixture 20'
assert solve([Entry(2, 3), Entry(0, 3), Entry(1, 3), Entry(2, 5), Entry(0, 2), Entry(3, 5), Entry(2, 5), Entry(0, 5)], 6) == Report(4, 1, 6), 'fixture 21'
assert solve([Entry(3, 4), Entry(2, 3), Entry(1, 2), Entry(0, 1), Entry(0, 4)], 6) == Report(5, 1, 10), 'fixture 22'
assert solve([Entry(0, 2), Entry(1, 2), Entry(2, 3), Entry(1, 4)], 5) == Report(3, 1, 4), 'fixture 23'
